-- DRAFT: P0 必须先选择覆盖 DB/WAL/索引的加密方案；本 SQL 本身不加密数据库。
PRAGMA foreign_keys = ON;
BEGIN IMMEDIATE;
CREATE TABLE schema_migrations (version INTEGER PRIMARY KEY CHECK(version > 0), checksum TEXT NOT NULL, applied_at INTEGER NOT NULL);
CREATE TABLE accounts (account_id TEXT PRIMARY KEY, public_key BLOB NOT NULL, protected_profile BLOB NOT NULL, identity_key_ref TEXT, revocation_version INTEGER NOT NULL DEFAULT 0 CHECK(revocation_version >= 0));
CREATE TABLE device_credentials (device_id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(account_id), credential BLOB NOT NULL, endpoint_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','revoked','pending')), version INTEGER NOT NULL CHECK(version >= 0));
CREATE TABLE trusted_contacts (account_id TEXT PRIMARY KEY REFERENCES accounts(account_id), trust_anchor BLOB NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','accepted','blocked')), verified_at INTEGER);
CREATE TABLE conversations (conversation_id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('direct','group','self_sync')), coordinator_id TEXT NOT NULL, protected_metadata BLOB NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','active','paused','left','dissolved')));
CREATE TABLE conversation_devices (conversation_id TEXT NOT NULL REFERENCES conversations(conversation_id), device_id TEXT NOT NULL REFERENCES device_credentials(device_id), account_id TEXT NOT NULL REFERENCES accounts(account_id), joined_seq INTEGER NOT NULL CHECK(joined_seq >= 0), left_seq INTEGER, PRIMARY KEY(conversation_id, device_id, joined_seq), CHECK(left_seq IS NULL OR left_seq >= joined_seq));
CREATE TABLE group_policy_snapshots (conversation_id TEXT PRIMARY KEY REFERENCES conversations(conversation_id), control_head BLOB NOT NULL, policy_version INTEGER NOT NULL CHECK(policy_version >= 0), mls_epoch INTEGER NOT NULL CHECK(mls_epoch >= 0), verified_seq INTEGER NOT NULL CHECK(verified_seq >= 0), log_hash BLOB NOT NULL, protected_policy BLOB NOT NULL);
CREATE TABLE group_log_entries (conversation_id TEXT NOT NULL REFERENCES conversations(conversation_id), group_seq INTEGER NOT NULL CHECK(group_seq > 0), submission_id TEXT NOT NULL, candidate_hash BLOB NOT NULL, log_hash BLOB NOT NULL, protected_entry BLOB NOT NULL, PRIMARY KEY(conversation_id, group_seq), UNIQUE(conversation_id, submission_id));
CREATE TABLE pending_group_operations (operation_id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(conversation_id), expected_head BLOB NOT NULL, request_hash BLOB NOT NULL, protected_operation BLOB NOT NULL, state TEXT NOT NULL CHECK(state IN ('waiting','preparing','submitted','accepted','rejected','cancelled','unknown')));
CREATE TABLE mls_state_records (conversation_id TEXT NOT NULL REFERENCES conversations(conversation_id), record_key BLOB NOT NULL, protected_value BLOB NOT NULL, record_version INTEGER NOT NULL CHECK(record_version >= 0), PRIMARY KEY(conversation_id, record_key));
CREATE TABLE key_packages (package_hash BLOB PRIMARY KEY, device_id TEXT NOT NULL REFERENCES device_credentials(device_id), public_package BLOB NOT NULL, protected_private_record BLOB, expires_at INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('available','claimed','consumed','expired')));
CREATE TABLE drafts (draft_id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(conversation_id), operation_id TEXT NOT NULL UNIQUE, request_hash BLOB NOT NULL, protected_content BLOB NOT NULL, state TEXT NOT NULL CHECK(state IN ('queued','accepted','delivered','failed','cancelled','unknown')), created_at INTEGER NOT NULL);
CREATE TABLE message_attempts (submission_id TEXT PRIMARY KEY, origin TEXT NOT NULL CHECK(origin IN ('local_application','local_control','remote')), draft_id TEXT REFERENCES drafts(draft_id), operation_id TEXT REFERENCES pending_group_operations(operation_id), conversation_id TEXT NOT NULL REFERENCES conversations(conversation_id), mls_epoch INTEGER NOT NULL CHECK(mls_epoch >= 0), immutable_ciphertext BLOB NOT NULL, candidate_hash BLOB NOT NULL, state TEXT NOT NULL CHECK(state IN ('prepared','submitted','accepted','rejected','unknown')), CHECK((origin = 'local_application' AND draft_id IS NOT NULL AND operation_id IS NULL) OR (origin = 'local_control' AND operation_id IS NOT NULL AND draft_id IS NULL) OR (origin = 'remote' AND draft_id IS NULL AND operation_id IS NULL)));
CREATE TABLE messages (message_id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(conversation_id), draft_id TEXT REFERENCES drafts(draft_id), submission_id TEXT NOT NULL REFERENCES message_attempts(submission_id), author_account_id TEXT NOT NULL, author_device_id TEXT NOT NULL, group_seq INTEGER NOT NULL CHECK(group_seq > 0), protected_content BLOB NOT NULL, display_created_at INTEGER NOT NULL, send_state TEXT NOT NULL CHECK(send_state IN ('accepted','delivered')), UNIQUE(conversation_id, group_seq));
CREATE INDEX messages_page ON messages(conversation_id, group_seq DESC, message_id);
CREATE TABLE receipts (message_id TEXT NOT NULL REFERENCES messages(message_id), device_id TEXT NOT NULL, account_id TEXT NOT NULL, protected_receipt BLOB NOT NULL, persisted_at INTEGER NOT NULL, PRIMARY KEY(message_id, device_id));
CREATE TABLE outbox_jobs (job_id TEXT PRIMARY KEY, dedup_key TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, payload_ref TEXT NOT NULL, conversation_id TEXT REFERENCES conversations(conversation_id), depends_on TEXT REFERENCES outbox_jobs(job_id), state TEXT NOT NULL CHECK(state IN ('pending','leased','complete','failed','cancelled')), retry_count INTEGER NOT NULL DEFAULT 0 CHECK(retry_count >= 0), retry_at INTEGER NOT NULL, lease_owner TEXT, lease_until INTEGER, lease_version INTEGER NOT NULL DEFAULT 0 CHECK(lease_version >= 0), cancel_requested INTEGER NOT NULL DEFAULT 0 CHECK(cancel_requested IN (0,1)));
CREATE INDEX outbox_due ON outbox_jobs(state, retry_at, lease_until);
CREATE TABLE inbox_dedup (conversation_id TEXT NOT NULL REFERENCES conversations(conversation_id), event_id TEXT NOT NULL, submission_id TEXT NOT NULL, content_hash BLOB NOT NULL, PRIMARY KEY(conversation_id, event_id));
CREATE TABLE sync_cursors (resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, owner_device_id TEXT NOT NULL, protected_cursor BLOB NOT NULL, version INTEGER NOT NULL CHECK(version >= 0), PRIMARY KEY(resource_type, resource_id, owner_device_id));
CREATE TABLE attachments (attachment_id TEXT PRIMARY KEY, protected_descriptor BLOB NOT NULL, plain_size INTEGER NOT NULL CHECK(plain_size >= 0), chunk_count INTEGER NOT NULL CHECK(chunk_count > 0), state TEXT NOT NULL CHECK(state IN ('staging','imported','uploading','available','downloading','failed','cancelled','collecting')));
CREATE TABLE attachment_chunks (attachment_id TEXT NOT NULL REFERENCES attachments(attachment_id), chunk_index INTEGER NOT NULL CHECK(chunk_index >= 0), cipher_hash BLOB NOT NULL, cache_ref TEXT NOT NULL, plain_size INTEGER NOT NULL CHECK(plain_size >= 0), uploaded INTEGER NOT NULL DEFAULT 0 CHECK(uploaded IN (0,1)), downloaded INTEGER NOT NULL DEFAULT 0 CHECK(downloaded IN (0,1)), PRIMARY KEY(attachment_id, chunk_index));
CREATE TABLE plugin_preferences (plugin_id TEXT PRIMARY KEY, protected_host_preferences BLOB NOT NULL);
CREATE TABLE revocation_jobs (job_id TEXT PRIMARY KEY, device_id TEXT NOT NULL REFERENCES device_credentials(device_id), revocation_version INTEGER NOT NULL CHECK(revocation_version > 0), state TEXT NOT NULL CHECK(state IN ('pending','partial','complete','failed')));
CREATE TABLE revocation_group_jobs (job_id TEXT NOT NULL REFERENCES revocation_jobs(job_id), conversation_id TEXT NOT NULL REFERENCES conversations(conversation_id), operation_id TEXT REFERENCES pending_group_operations(operation_id), state TEXT NOT NULL CHECK(state IN ('pending','submitted','complete','failed')), PRIMARY KEY(job_id, conversation_id));
CREATE TABLE mailbox_consumptions (node_id TEXT NOT NULL, device_id TEXT NOT NULL, item_id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('persisted','quarantined','ack_pending','acked')), protected_diagnostic BLOB, PRIMARY KEY(node_id, device_id, item_id));
COMMIT;
